#include <ESP32Servo.h>
Servo pan, tilt;

void point(float az, float el) {
  if (el < 0) return;                  // below the horizon: do nothing
  float p = az, t = el;
  if (az > 180) {                      // the other half of the sky:
    p = az - 180;                      //   turn to the opposite side
    t = 180 - el;                      //   and lean over the top
  }
  pan.write(p);                        // 0 = north, 90 = east, 180 = south
  tilt.write(t);                       // 0 = flat, 90 = straight up
}

void setup() {
  pan.attach(18, 500, 2400);           // pin, shortest and longest pulse in us
  tilt.attach(19, 500, 2400);
  point(270, 30);                      // test: west, 30 degrees up
}
void loop() {}

#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>
#include <ArduinoJson.h>             // version 7

bool getIss(float &lat, float &lon, float &altKm) {
  WiFiClientSecure client;
  client.setInsecure();              // fine for a public data feed, not for secrets
  HTTPClient http;
  http.begin(client, "https://api.wheretheiss.at/v1/satellites/25544");
  if (http.GET() != 200) { http.end(); return false; }

  JsonDocument doc;
  deserializeJson(doc, http.getString());
  lat = doc["latitude"];  lon = doc["longitude"];  altKm = doc["altitude"];
  http.end();
  return true;
}
