const float R = 6371.0, RAD = PI / 180.0;

void azEl(float myLat, float myLon, float lat, float lon, float altKm,
          float &az, float &el) {
  float a = myLat * RAD, b = myLon * RAD, c = lat * RAD, d = lon * RAD;
  float r = R + altKm;
  // vector from you to the ISS in km, measured from Earth's centre
  float x = r * cos(c) * cos(d) - R * cos(a) * cos(b);
  float y = r * cos(c) * sin(d) - R * cos(a) * sin(b);
  float z = r * sin(c) - R * sin(a);
  float east  = -sin(b) * x + cos(b) * y;
  float north = -sin(a) * cos(b) * x - sin(a) * sin(b) * y + cos(a) * z;
  float up    = cos(a) * cos(b) * x + cos(a) * sin(b) * y + sin(a) * z;
  az = fmod(atan2(east, north) / RAD + 360, 360);
  el = atan2(up, sqrt(east * east + north * north)) / RAD;
}

void loop() {
  float lat, lon, altKm, az, el;
  if (getIss(lat, lon, altKm)) {
    azEl(MY_LAT, MY_LON, lat, lon, altKm, az, el);
    Serial.printf("ISS az %.0f  el %.0f\n", az, el);
    point(az, el);
  }
  delay(5000);                         // the ISS moves about 38 km in 5 s
}
